        F("Лежандр символы", r"\left(\frac ap\right)\in\{-1,0,1\},\quad\left(\frac{ab}p\right)=\left(\frac ap\right)\left(\frac bp\right)", r"$p$ тақ жай.", r""),
        F("Эйлер критерийі", r"\left(\frac ap\right)\equiv a^{\frac{p-1}2}\pmod p", r"Бір дәрежелеу.", r""),
